// NewSaveStackPayload builds a onboarding service saveStack endpoint payload.
func NewSaveStackPayload(body *SaveStackRequestBody, sessionToken *string) *onboarding.SaveStackPayload {
	v := &onboarding.SaveStackPayload{
		MdmVendor: *body.MdmVendor,
	}
	v.Providers = make([]*onboarding.OnboardingSelectedProvider, len(body.Providers))
	for i, val := range body.Providers {
		if val == nil {
			v.Providers[i] = nil
			continue
		}
		v.Providers[i] = unmarshalOnboardingSelectedProviderRequestBodyToOnboardingOnboardingSelectedProvider(val)
	}
	v.ProductSlugs = make([]string, len(body.ProductSlugs))
	for i, val := range body.ProductSlugs {
		v.ProductSlugs[i] = val
	}
	v.SessionToken = sessionToken

	return v
}

