// ValidateSaveStackRequestBody runs the validations defined on
// SaveStackRequestBody
func ValidateSaveStackRequestBody(body *SaveStackRequestBody) (err error) {
	if body.Providers == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("providers", "body"))
	}
	if body.ProductSlugs == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("product_slugs", "body"))
	}
	if body.MdmVendor == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("mdm_vendor", "body"))
	}
	for _, e := range body.Providers {
		if e != nil {
			if err2 := ValidateOnboardingSelectedProviderRequestBody(e); err2 != nil {
				err = goa.MergeErrors(err, err2)
			}
		}
	}
	if body.MdmVendor != nil {
		if !(*body.MdmVendor == "jamf" || *body.MdmVendor == "intune" || *body.MdmVendor == "iru" || *body.MdmVendor == "none") {
			err = goa.MergeErrors(err, goa.InvalidEnumValueError("body.mdm_vendor", *body.MdmVendor, []any{"jamf", "intune", "iru", "none"}))
		}
	}
	return
}

// ValidateSelectUseCaseRequestBody runs the validations defined on
// SelectUseCaseRequestBody
func ValidateSelectUseCaseRequestBody(body *SelectUseCaseRequestBody) (err error) {
	if body.UseCase == nil {
		err = goa.MergeErrors(err, goa.MissingFieldError("use_case", "body"))
	}
	if body.UseCase != nil {
		if !(*body.UseCase == "observability" || *body.UseCase == "cost-tracking" || *body.UseCase == "security" || *body.UseCase == "mcp-gateway") {
			err = goa.MergeErrors(err, goa.InvalidEnumValueError("body.use_case", *body.UseCase, []any{"observability", "cost-tracking", "security", "mcp-gateway"}))
		}
	}
	return
}

